//! Helpers for comparing against golden data generated by PyTorch (see `tools/golden`).

#![allow(dead_code)]

use std::cell::RefCell;
use std::collections::{BTreeMap, HashSet};

use homura::{DType, Tensor};

/// The tensors of one golden file, keyed by `"<case>/<name>"`.
pub struct Golden {
    tensors: BTreeMap<String, Tensor>,
}

impl Golden {
    pub fn load(file: &str) -> Golden {
        let path = format!("{}/tests/golden/{file}", env!("CARGO_MANIFEST_DIR"));
        let tensors = homura::load_safetensors(&path)
            .unwrap_or_else(|e| panic!("can't load {path}: {e}"))
            .into_iter()
            .collect();
        Golden { tensors }
    }

    pub fn get(&self, key: &str) -> Tensor {
        self.tensors
            .get(key)
            .unwrap_or_else(|| panic!("golden data has no tensor {key:?}"))
            .clone()
    }

    /// The names of all cases, in sorted order.
    pub fn cases(&self) -> Vec<String> {
        let mut cases: Vec<String> = self
            .tensors
            .keys()
            .map(|k| k.split_once('/').unwrap().0.to_string())
            .collect();
        cases.dedup();
        cases
    }

    /// The tensor names stored for `case`.
    pub fn names(&self, case: &str) -> Vec<String> {
        let prefix = format!("{case}/");
        self.tensors
            .keys()
            .filter_map(|k| k.strip_prefix(&prefix).map(String::from))
            .collect()
    }
}

/// Access to one case that remembers which tensors were used.
pub struct Case<'a> {
    pub golden: &'a Golden,
    pub name: &'a str,
    used: RefCell<HashSet<String>>,
}

impl<'a> Case<'a> {
    pub fn new(golden: &'a Golden, name: &'a str) -> Self {
        Case {
            golden,
            name,
            used: RefCell::new(HashSet::new()),
        }
    }

    /// An input tensor of this case.
    pub fn input(&self, name: &str) -> Tensor {
        self.used.borrow_mut().insert(name.to_string());
        self.golden.get(&format!("{}/{name}", self.name))
    }

    /// Compares `actual` with the stored tensor `name` of this case.
    pub fn check(&self, name: &str, actual: &Tensor) {
        self.used.borrow_mut().insert(name.to_string());
        let expected = self.golden.get(&format!("{}/{name}", self.name));
        assert_close(actual, &expected, &format!("{}/{name}", self.name));
    }

    /// Compares `actual` with the stored tensor `name` of this case with `compare`, which gets
    /// both tensors.
    pub fn check_with(&self, name: &str, actual: &Tensor, compare: impl FnOnce(&Tensor, &Tensor)) {
        self.used.borrow_mut().insert(name.to_string());
        compare(actual, &self.golden.get(&format!("{}/{name}", self.name)));
    }

    /// Panics if some stored tensor of this case was neither used as input nor checked.
    pub fn assert_all_used(&self) {
        let used = self.used.borrow();
        for n in self.golden.names(self.name) {
            assert!(
                used.contains(&n),
                "golden tensor {}/{n} was not used",
                self.name
            );
        }
    }
}

/// Default tolerances `(rtol, atol)` for a dtype: about one rounding step for half types,
/// `1e-6` for `f32`, and exact equality for integers and bools.
pub fn tolerance(dtype: DType) -> (f64, f64) {
    match dtype {
        DType::F16 => (2f64.powi(-10), 1e-7),
        DType::BF16 => (2f64.powi(-7), 1e-7),
        DType::F32 => (1e-6, 1e-6),
        DType::F64 => (1e-12, 1e-12),
        _ => (0.0, 0.0),
    }
}

pub fn assert_close(actual: &Tensor, expected: &Tensor, what: &str) {
    let (rtol, atol) = tolerance(expected.dtype());
    assert_close_tol(actual, expected, rtol, atol, what);
}

/// Asserts equal shape and dtype, and then for floating point tensors NaN in the same places and
/// `|a - e| <= atol + rtol * |e|`. Integer and bool tensors must be exactly equal; they are
/// compared as `i64`, never through floats, which can't represent every `i64`.
pub fn assert_close_tol(actual: &Tensor, expected: &Tensor, rtol: f64, atol: f64, what: &str) {
    assert_eq!(actual.shape(), expected.shape(), "{what}: shape");
    assert_eq!(actual.dtype(), expected.dtype(), "{what}: dtype");
    if !expected.dtype().is_floating_point() {
        let exact = |t: &Tensor| t.to(DType::I64).to_vec::<i64>();
        let (a, e) = (exact(actual), exact(expected));
        if let Some(i) = (0..a.len()).find(|&i| a[i] != e[i]) {
            panic!(
                "{what}: element {i} differs: got {}, expected {}\n  actual: {actual:?}\n  \
                 expected: {expected:?}",
                a[i], e[i]
            );
        }
        return;
    }
    let a = actual.to(DType::F64).to_vec::<f64>();
    let e = expected.to(DType::F64).to_vec::<f64>();
    for (i, (&x, &y)) in a.iter().zip(&e).enumerate() {
        let ok = if y.is_nan() || x.is_nan() {
            x.is_nan() && y.is_nan()
        } else if y.is_infinite() || x.is_infinite() {
            x == y
        } else {
            (x - y).abs() <= atol + rtol * y.abs()
        };
        if !ok {
            panic!(
                "{what}: element {i} differs: got {x:e}, expected {y:e}\n  actual: {actual:?}\n  \
                 expected: {expected:?}"
            );
        }
    }
}
